const G=2;const S=0.7071068;
const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-S,0,0,S],down:[S,0,0,S],left:[0,0,S,S],right:[0,0,-S,S]};
function dist(s){return (G-s.c)+(G-s.r);}
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:'Reach the green goal square.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;const s={...state};
if(dist(s)===0){s.msg='Already won. Press Reset to play again.';return s;}
if(a==='hint'){s.hint=s.c<G?'right':'up';s.msg='Hint: move '+s.hint[0].toUpperCase()+s.hint.slice(1)+'.';return s;}
const d=D[a];if(!d)return state;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>G||r<0||r>G){s.msg='That move would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=null;
if(dist(s)===0)s.msg='You reached the goal in '+s.moves+' moves. Shortest possible: 4.';
else s.msg='Moved '+a+'. '+dist(s)+' steps to go.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const x=(s.c-1)*1.1,z=(1-s.r)*1.1;const won=dist(s)===0;
const y=won?0.48:0.4;
const nodes={tokenN:{position:[x,y,z]},hintN:{visible:!!s.hint,position:[x,y,z]}};
if(s.hint)nodes.hintN.quaternion=Q[s.hint];
return {nodes,readouts:{moves:s.moves,steps:dist(s)},goal:{status:won?'won':'playing',message:s.msg}};}
